const p=await browser.getPage('main');
await p.evaluate(payload=>{
 if(localStorage.getItem('delivery-county-single-slot-v1')!==null)throw Error('Origin already has progress');
 if(!globalThis.__runtimeProfileSeed){if(payload.index!==0)throw Error('First seed chunk missing');globalThis.__runtimeProfileSeed={total:payload.total,parts:[]};}
 const s=globalThis.__runtimeProfileSeed;if(s.total!==payload.total||s.parts.length!==payload.index)throw Error('Unexpected seed chunk sequence');s.parts.push(payload.part);return {received:s.parts.length,total:s.total};
},{"index": 1, "total": 3, "part": ""});
